    $c.util.getComponent('dma_fnSavePasswordReq').set('method', "modifySalesPasswordInfo");
    fm.action = "/sales/sales.do";
    fm.target = "_self";
    await scwin.tx_test();
    /* sdd-asis-lifecycle:end */
};


